/**
 * "Discard draft" on the request form: asks for confirmation (NanoflowCommons.ShowConfirmation: a call-nanoflow button has no confirmation setting of its own; mxcli stores one but the runtime ignores it, seen 2026-10-09), rolls back the form's unsaved edits (a blank required title would otherwise block the call), then discards the draft through ACT_TravelRequest_Discard (owner and Draft checks, delete, message, close page).
 */
create or modify nanoflow TravelApproval.ACT_TravelRequest_DiscardFromForm (
  $TravelRequest: TravelApproval.TravelRequest
)
begin
  @start(200, 200)
  @position(310, 200)
  $Confirmed = call javascript action NanoflowCommons.ShowConfirmation(titleCaption = '', Question = 'Discard this draft? It cannot be undone.', CancelButtonCaption = 'Keep', ProceedButtonCaption = 'Discard');
  @position(470, 200)
  @curve(from: (15, 0))
  @caption 'not($Confirmed)'
  if not($Confirmed) then
    @position(640, 300)
    return;
  end if;
  @position(750, 200)
  rollback $TravelRequest;
  @position(910, 200)
  call microflow TravelApproval.ACT_TravelRequest_Discard(TravelRequest = $TravelRequest);
  @position(1150, 200)
  return;
end;

grant execute on nanoflow TravelApproval.ACT_TravelRequest_DiscardFromForm to TravelApproval.Requestor;
/
